   536|        setUint32(16);
   537|        setUint16(1);           // PCM
   538|        setUint16(numOfChan);
   539|        setUint32(buffer.sampleRate);
   540|        setUint32(buffer.sampleRate * 2 * numOfChan);
   541|        setUint16(numOfChan * 2);
   542|        setUint16(16);          // 16-bit
   543|
   544|        setUint32(0x61746164);  // "data"
   545|        setUint32(length - pos - 4);
   546|
   547|        for (let i = 0; i < buffer.numberOfChannels; i++) {
   548|            channels.push(buffer.getChannelData(i));
   549|        }
   550|
   551|        while (pos < length) {
   552|            for (let i = 0; i < numOfChan; i++) {
   553|                let sample = Math.max(-1, Math.min(1, channels[i][offset]));
   554|                sample = (sample < 0 ? sample * 0x8000 : sample * 0x7FFF) | 0;
   555|                view.setInt16(pos, sample, true);
   556|                pos += 2;
   557|            }
   558|            offset++;
   559|        }
   560|
   561|        return new Blob([out], { type: 'audio/wav' });
   562|    }
