     2|export class MidiHandler {
     3|    private midiAccess: any = null;
     4|    private activeInput: any = null;
     5|    private activeNotes: Map<number, number> = new Map(); // Note -> Velocity
     6|
     7|    // Callbacks
     8|    private onNoteChangeCallback: ((note: number | null) => void) | null = null;
     9|    private onConnectionChangeCallback: ((isConnected: boolean) => void) | null = null;
    10|    private onRawNoteCallback: ((note: number, velocity: number) => void) | null = null;  // For visualization
    11|
    12|    constructor() {
    13|        this.initialize();
    14|    }
    15|
    16|    private async initialize() {
    17|        try {
    18|            if ((navigator as any).requestMIDIAccess) {
    19|                this.midiAccess = await (navigator as any).requestMIDIAccess();
    20|
    21|                // Get first available input
    22|                const inputs = this.midiAccess.inputs.values();
    23|                for (let input of inputs) {
    24|                    this.setInput(input);
    25|                    break; // Just grab the first one for now
    26|                }
    27|
    28|                this.midiAccess.onstatechange = (e: any) => {
    29|                    console.log('MIDI State Change:', e.port.name, e.port.state, e.port.connection);
    30|                    if (e.port.type === 'input') {
    31|                        if (e.port.state === 'connected' && !this.activeInput) {
    32|                            this.setInput(e.port);
    33|                        } else if (e.port.state === 'disconnected' && this.activeInput && this.activeInput.id === e.port.id) {
    34|                            this.activeInput = null;
    35|                            if (this.onConnectionChangeCallback) {
    36|                                this.onConnectionChangeCallback(false);
    37|                            }
    38|                        }
    39|                    }
    40|                };
    41|            } else {
    42|                console.warn('Web MIDI API not supported in this browser.');
    43|            }
    44|        } catch (err) {
    45|            console.error('MIDI Access Failed:', err);
    46|        }
    47|    }
    48|
    49|    private setInput(input: any) {
    50|        this.activeInput = input;
    51|        console.log(`MIDI Input Selected: ${input.name}`);
    52|
    53|        input.onmidimessage = (message: any) => {
    54|            this.handleMessage(message);
    55|        };
    56|
    57|        if (this.onConnectionChangeCallback) {
    58|            this.onConnectionChangeCallback(true);
    59|        }
    60|    }
    61|
    62|    private handleMessage(message: any) {
    63|        const [status, data1, data2] = message.data;
    64|        const command = status & 0xF0;
    65|        // const channel = status & 0x0F;
    66|        const note = data1;
    67|        const velocity = data2;
    68|
    69|        // Note On
    70|        if (command === 0x90 && velocity > 0) {
    71|            this.activeNotes.set(note, velocity);
    72|            this.triggerHighestNote();
    73|            if (this.onRawNoteCallback) this.onRawNoteCallback(note, velocity);
    74|        }
    75|        // Note Off (or Note On with vel 0)
    76|        else if (command === 0x80 || (command === 0x90 && velocity === 0)) {
    77|            this.activeNotes.delete(note);
    78|            this.triggerHighestNote();
    79|            if (this.onRawNoteCallback) this.onRawNoteCallback(note, 0);
    80|        }
    81|    }
    82|
    83|    private triggerHighestNote() {
    84|        if (!this.onNoteChangeCallback) return;
    85|
    86|        if (this.activeNotes.size === 0) {
    87|            this.onNoteChangeCallback(null);
    88|            return;
    89|        }
    90|
    91|        // Monophonic: Last note priority or Highest note?
    92|        // Let's implement Highest Note Priority for standard synth feel
    93|        let highestNote = -1;
    94|        for (let note of this.activeNotes.keys()) {
    95|            if (note > highestNote) highestNote = note;
    96|        }
    97|
    98|        if (highestNote !== -1) {
    99|            this.onNoteChangeCallback(highestNote);
   100|        }
   101|    }
   102|
   103|    public setNoteChangeCallback(callback: (note: number | null) => void) {
   104|        this.onNoteChangeCallback = callback;
   105|    }
   106|
   107|    public setRawNoteCallback(callback: (note: number, velocity: number) => void) {
   108|        this.onRawNoteCallback = callback;
   109|    }
   110|
   111|    public setConnectionChangeCallback(callback: (isConnected: boolean) => void) {
   112|        this.onConnectionChangeCallback = callback;
   113|    }
   114|
   115|    public getInputs(): { id: string, name: string }[] {
   116|        if (!this.midiAccess) return [];
   117|        const inputs: { id: string, name: string }[] = [];
   118|        this.midiAccess.inputs.forEach((input: any) => {
   119|            inputs.push({ id: input.id, name: input.name });
   120|        });
   121|        return inputs;
   122|    }
   123|
   124|    public selectInput(id: string) {
   125|        if (!this.midiAccess) return;
   126|        const input = this.midiAccess.inputs.get(id);
   127|        if (input) {
   128|            this.setInput(input);
   129|        }
   130|    }
   131|
   132|    public simulateNoteOn(note: number, velocity: number) {
   133|        this.activeNotes.set(note, velocity);
   134|        this.triggerHighestNote();
   135|        // Allow visualization update if needed (e.g. if driven by computer keyboard later)
   136|        if (this.onRawNoteCallback) this.onRawNoteCallback(note, velocity);
   137|    }
   138|
   139|    public simulateNoteOff(note: number) {
   140|        this.activeNotes.delete(note);
   141|        this.triggerHighestNote();
   142|        if (this.onRawNoteCallback) this.onRawNoteCallback(note, 0);
   143|    }
   144|}
