{"content": "     1|// Audio analysis and spectral volume conversion
     2|// Converts WAV/audio files into 3D spectral volume data using FFT
     3|
     4|export class AudioAnalyzer {
     5|    private audioContext: AudioContext;
     6|
     7|    constructor() {
     8|        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
     9|    }
    10|
    11|    /**
    12|     * Analyze multiple files for morphing
    13|     * Each file is placed at a different Y position in the volume
    14|     * All files are time-stretched to the same Z length
    15|     */
    16|    public async analyzeMultipleFiles(
    17|        files: File[],
    18|        volumeSize: { x: number, y: number, z: number },
    19|        onProgress?: (percent: number) => void
    20|    ): Promise<Float32Array> {
    21|        const { x: xSize, y: ySize, z: zSize } = volumeSize;
    22|        const numFiles = files.length;
    23|
    24|        console.log(`Analyzing ${numFiles} files for morphing into ${xSize}x${ySize}x${zSize} volume`);
    25|
    26|        // Initialize volume with zeros
    27|        const volumeData = new Float32Array(xSize * ySize * zSize * 4); // RGBA
    28|
    29|        // Process each file
    30|        for (let fileIdx = 0; fileIdx < numFiles; fileIdx++) {
    31|            const file = files[fileIdx];
    32|
    33|            // Load and decode audio
    34|            const arrayBuffer = await file.arrayBuffer();
    35|            const audioBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
    36|            const channelData = audioBuffer.getChannelData(0);
    37|            const sampleRate = audioBuffer.sampleRate;
    38|
    39|            console.log(`  [${fileIdx + 1}/${numFiles}] ${file.name}: ${audioBuffer.duration.toFixed(2)}s`);
    40|
    41|            // Calculate which Y index this file should occupy
    42|            // For 1 file: Y=0 (middle)
    43|            // For 2 files: Y=-1, Y=1 (first and last)
    44|            // For 3+ files: equally spaced from -1 to 1
    45|            const yPosition = numFiles === 1 ? 0 : -1 + (fileIdx / (numFiles - 1)) * 2;
    46|            const yIndex = Math.round((yPosition + 1) * 0.5 * (ySize - 1));
    47|
    48|            // Time-stretch audio to fit Z dimension
    49|            const fftSize = 2048;
    50|            const samplesNeeded = zSize * fftSize;
    51|            const processedData = this.timeStretch(channelData, samplesNeeded);
    52|
    53|            // Frequency mapping constants
    54|            const minFreq = 20;
    55|            const maxFreq = 20000;
    56|
    57|            // Process each Z slice (time)
    58|            for (let iz = 0; iz < zSize; iz++) {
    59|                const startSample = iz * fftSize;
    60|                const signal = new Float32Array(fftSize);
    61|
    62|                // Extract window
    63|                for (let i = 0; i < fftSize; i++) {
    64|                    if (startSample + i < processedData.length) {
    65|                        signal[i] = processedData[startSample + i];
    66|                    }
    67|                }
    68|
    69|                // Apply Hann window
    70|                for (let i = 0; i < fftSize; i++) {
    71|                    signal[i] *= 0.5 * (1 - Math.cos(2 * Math.PI * i / fftSize));
    72|                }
    73|
    74|                // Perform FFT
    75|                const spectrum = this.simpleFFT(signal);
    76|
    77|                // Map spectrum to X axis (Linear Frequency 0-22kHz)
    78|                for (let ix = 0; ix < xSize; ix++) {
    79|                    const normalizedX = ix / xSize;
    80|                    const freq = minFreq + (maxFreq - minFreq) * normalizedX;
    81|                    const binIndex = Math.floor(freq * fftSize / sampleRate);
    82|                    const safeBinIndex = Math.max(0, Math.min(spectrum.length - 1, binIndex));
    83|                    const magnitude = spectrum[safeBinIndex] || 0;
    84|
    85|                    // Convert to dB scale
    86|                    let val = 0;
    87|                    if (magnitude > 0.000001) {
    88|                        const db = 20 * Math.log10(magnitude);
    89|                        val = (db + 60) / 60;
    90|                        val = Math.max(0, Math.min(1, val));
    91|                    }
    92|
    93|                    // Write to the specific Y slice for this file
    94|                    const idx = (iz * ySize * xSize + yIndex * xSize + ix) * 4;
    95|
    96|                    volumeData[idx] = val;                        // R: Magnitude
    97|                    volumeData[idx + 1] = ix / xSize;             // G: Phase (freq-based)
    98|                    volumeData[idx + 2] = ix / xSize;             // B: Pan
    99|                    volumeData[idx + 3] = iz / zSize;             // A: Width
   100|                }
   101|
   102|                // Report progress
   103|                if (onProgress && iz % 10 === 0) {
   104|                    const fileProgress = (fileIdx / numFiles) * 100;
   105|                    const sliceProgress = ((iz / zSize) / numFiles) * 100;
   106|                    onProgress(fileProgress + sliceProgress);
   107|                }
   108|
   109|                // Yield to main thread periodically
   110|                if (iz % 20 === 0) {
   111|                    await new Promise(resolve => requestAnimationFrame(resolve));
   112|                }
   113|            }
   114|        }
   115|
   116|        if (onProgress) onProgress(100);
   117|        console.log('✓ Multi-file morphing volume created');
   118|        return volumeData;
   119|    }
   120|
   121|    public async analyzeFile(
   122|        file: File,
   123|        volumeSize: { x: number, y: number, z: number },
   124|        onProgress?: (percent: number) => void
   125|    ): Promise<{ data: Float32Array, adjustedSize: { x: number, y: number, z: number } }> {
   126|        // Load audio file
   127|        const arrayBuffer = await file.arrayBuffer();
   128|        const audioBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
   129|
   130|        // Get audio data (mix to mono from stereo)
   131|        const channelData = audioBuffer.getChannelData(0);
   132|        const totalSamples = channelData.length;
   133|        const sampleRate = audioBuffer.sampleRate;
   134|
   135|        console.log(`Analyzing: ${file.name}, ${audioBuffer.duration.toFixed(2)}s, ${sampleRate}Hz, ${totalSamples} samples`);
   136|
   137|        const { x: xSize, y: ySize, z: zSize } = volumeSize;
   138|
   139|        // Minimum samples needed for good FFT (2048 is a good FFT size)
   140|        const minFFTSize = 2048;
   141|
   142|        // Calculate total samples needed to fill the volume
   143|        const samplesNeeded = zSize * ySize * minFFTSize;
   144|
   145|        let processedData: Float32Array;
   146|
   147|        if (totalSamples < samplesNeeded) {
   148|            // Time-stretch (interpolate) to fill the volume
   149|            console.log(`Time-stretching audio: ${totalSamples} → ${samplesNeeded} samples (${(samplesNeeded / totalSamples).toFixed(2)}x)`);
   150|            if (onProgress) onProgress(10);
   151|            processedData = this.timeStretch(channelData, samplesNeeded);
   152|            if (onProgress) onProgress(20);
   153|        } else {
   154|            // Use as-is or downsample if much longer
   155|            processedData = channelData;
   156|            if (onProgress) onProgress(15);
   157|        }
   158|
   159|        const volumeData = new Float32Array(xSize * ySize * zSize * 4); // RGBA
   160|
   161|        // Split sample by Z depth (morph layers)
   162|
   163|        const totalIterations = zSize;
   164|        let iterationCount = 0;
   165|        let lastYieldTime = performance.now();
   166|
   167|        // We will process the audio in Z steps (Time)
   168|        // Each Z step represents a point in time
   169|        // X is Frequency (Logarithmic)
   170|        // Y is replicated
   171|
   172|        const stepSize = Math.floor(processedData.length / zSize);
   173|
   174|        // Frequency mapping constants
   175|        const minFreq = 20;
